begin;
update public.questions set subject = 'Economy', topic = 'Industry, Infrastructure, Energy & Services', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about the industrial smart cities approved in 2024:', body_hi = '2024 में स्वीकृत औद्योगिक स्मार्ट शहरों के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Statements 1 and 2 are correct. In August 2024 the Union Cabinet approved twelve greenfield industrial cities along the industrial corridors, developed by the National Industrial Corridor Development and Implementation Trust with the States, which provide the land; the aim is to cut the time and uncertainty of land acquisition and approvals by offering developed plots, utilities and connectivity in advance. Statement 3 is wrong: the sites are spread across ten States, many of them inland -- among them Agra and Prayagraj in Uttar Pradesh, Gaya in Bihar, Jodhpur-Pali in Rajasthan, Zaheerabad in Telangana and Khurpia in Uttarakhand -- because the corridors follow freight routes and dedicated freight corridors as much as the coast.', explanation_hi = 'कथन 1 और 2 सही हैं। अगस्त 2024 में केंद्रीय मंत्रिमंडल ने औद्योगिक गलियारों के साथ बारह ग्रीनफ़ील्ड औद्योगिक शहरों को स्वीकृति दी, जिन्हें राष्ट्रीय औद्योगिक गलियारा विकास और कार्यान्वयन ट्रस्ट राज्यों के साथ विकसित करता है, और राज्य भूमि देते हैं; उद्देश्य पहले से विकसित भूखंड, उपयोगिताएँ और संपर्क देकर भूमि-अधिग्रहण और स्वीकृतियों का समय और अनिश्चितता घटाना है। कथन 3 ग़लत है: ये स्थल दस राज्यों में फैले हैं, उनमें से कई अंतर्देशीय -- जैसे उत्तर प्रदेश में आगरा और प्रयागराज, बिहार में गया, राजस्थान में जोधपुर-पाली, तेलंगाना में ज़हीराबाद और उत्तराखंड में खुरपिया -- क्योंकि गलियारे तट के साथ-साथ माल-मार्गों और समर्पित माल गलियारों का भी अनुसरण करते हैं।', concept_group_id = 'l3-t1-eco-industrial-smart-cities-2024', source_citation = 'Department for Promotion of Industry and Internal Trade: National Industrial Corridor Development Programme (Cabinet decision, August 2024).', question_data = '{"statements": ["Twelve of them were approved under the National Industrial Corridor Development Programme.", "They are planned as ''plug-and-play'' sites, with land and infrastructure ready before investors arrive.", "They are located only in coastal States, so that their output can be exported easily."], "statements_hi": ["इनमें से बारह को राष्ट्रीय औद्योगिक गलियारा विकास कार्यक्रम के अंतर्गत स्वीकृति दी गई।", "इन्हें ''प्लग-एंड-प्ले'' स्थलों के रूप में नियोजित किया गया है, जहाँ निवेशकों के आने से पहले भूमि और बुनियादी ढाँचा तैयार रहे।", "ये केवल तटीय राज्यों में स्थित हैं, ताकि इनका उत्पादन आसानी से निर्यात हो सके।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l3-t1-eco-critical-mineral-mission' returning concept_group_id;
update public.questions set subject = 'Economy', topic = 'Inclusive Growth, Welfare & Demography', type = 'match_the_following', difficulty = 'hard', body = 'Consider the following pairs of schemes and the ministries or departments that run them:', body_hi = 'योजनाओं और उन्हें चलाने वाले मंत्रालयों या विभागों के निम्नलिखित युग्मों पर विचार कीजिए:', explanation = 'The first, second and fourth pairs are correct. Dharti Aaba (2024) brings the schemes of many ministries together to saturate tribal-majority villages with roads, housing, water, health and livelihoods; the Accessible India Campaign (2015) aims to make public buildings, transport and websites accessible; and PM-AJAY merges earlier schemes to develop Scheduled Caste-majority villages and support SC livelihoods. The third pair is wrong: the rural arm of the Swachh Bharat Mission, which built household toilets and now works on solid and liquid waste in villages, is run by the Department of Drinking Water and Sanitation in the Ministry of Jal Shakti; the Ministry of Housing and Urban Affairs runs the urban mission.', explanation_hi = 'पहला, दूसरा और चौथा युग्म सही हैं। धरती आबा (2024) अनेक मंत्रालयों की योजनाओं को मिलाकर जनजाति-बहुल गाँवों को सड़क, आवास, पानी, स्वास्थ्य और आजीविका से संतृप्त करता है; सुगम्य भारत अभियान (2015) सार्वजनिक भवनों, परिवहन और वेबसाइटों को सुगम्य बनाना चाहता है; और PM-AJAY पुरानी योजनाओं को मिलाकर अनुसूचित जाति-बहुल गाँवों का विकास और SC आजीविकाओं को सहारा देता है। तीसरा युग्म ग़लत है: स्वच्छ भारत मिशन की ग्रामीण शाखा, जिसने घरेलू शौचालय बनवाए और अब गाँवों में ठोस और तरल अपशिष्ट पर काम करती है, जल शक्ति मंत्रालय का पेयजल और स्वच्छता विभाग चलाता है; आवासन और शहरी कार्य मंत्रालय शहरी मिशन चलाता है।', concept_group_id = 'l3-t3-eco-schemes-dajgua-sugamya-sbmg-pmajay', source_citation = 'Ministry of Tribal Affairs; Ministry of Social Justice and Empowerment; Ministry of Jal Shakti (Department of Drinking Water and Sanitation).', question_data = '{"list_1": ["1. Dharti Aaba Janjatiya Gram Utkarsh Abhiyan", "2. Sugamya Bharat Abhiyan (Accessible India Campaign)", "3. Swachh Bharat Mission (Grameen)", "4. Pradhan Mantri Anusuchit Jaati Abhyuday Yojana (PM-AJAY)"], "list_1_hi": ["1. धरती आबा जनजातीय ग्राम उत्कर्ष अभियान", "2. सुगम्य भारत अभियान", "3. स्वच्छ भारत मिशन (ग्रामीण)", "4. प्रधानमंत्री अनुसूचित जाति अभ्युदय योजना (PM-AJAY)"], "list_2": ["Ministry of Tribal Affairs", "Department of Empowerment of Persons with Disabilities", "Ministry of Housing and Urban Affairs", "Ministry of Social Justice and Empowerment"], "list_2_hi": ["जनजातीय कार्य मंत्रालय", "दिव्यांगजन सशक्तीकरण विभाग", "आवासन और शहरी कार्य मंत्रालय", "सामाजिक न्याय और अधिकारिता मंत्रालय"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l3-t3-eco-schemes-dajgua-sugamya-pmmvy-pmajay' returning concept_group_id;
update public.questions set subject = 'Environment & Ecology', topic = 'Climate Science & Mitigation', type = 'mcq', difficulty = 'medium', body = 'Ice cores drilled from the Antarctic and Greenland ice sheets are especially valuable to climate scientists mainly because:', body_hi = 'अंटार्कटिक और ग्रीनलैंड की हिम-चादरों से निकाले गए बर्फ़ के कोर (आइस कोर) जलवायु वैज्ञानिकों के लिए विशेष रूप से मूल्यवान क्यों हैं?', explanation = 'As snow piles up and is compressed into ice, it seals in small pockets of the atmosphere of the time, so analysing the bubbles gives carbon dioxide and methane levels going back about 800,000 years in Antarctic cores; the ratio of oxygen or hydrogen isotopes in the ice itself shows past temperatures, and layers of ash and dust mark eruptions and dry, windy periods. These records show that carbon dioxide and temperature rose and fell together through the ice-age cycles, and that today''s level -- above 420 parts per million -- is far higher than anything in that span, which is why ice cores are central evidence in assessments of human-caused warming.', explanation_hi = 'जब बर्फ़ जमा होकर दबती हुई हिम बनती है, तो वह उस समय के वायुमंडल की छोटी जेबों को बंद कर लेती है, इसलिए बुलबुलों के विश्लेषण से अंटार्कटिक कोरों में लगभग 8,00,000 वर्ष पीछे तक के कार्बन डाइऑक्साइड और मीथेन स्तर मिलते हैं; स्वयं बर्फ़ में ऑक्सीजन या हाइड्रोजन समस्थानिकों का अनुपात पिछले तापमान बताता है, और राख तथा धूल की परतें विस्फोटों और शुष्क, आँधी वाले कालों को चिह्नित करती हैं। ये अभिलेख दिखाते हैं कि हिमयुग-चक्रों में कार्बन डाइऑक्साइड और तापमान साथ-साथ चढ़ते-उतरते रहे, और आज का स्तर -- 420 भाग प्रति दस लाख से ऊपर -- उस पूरी अवधि के किसी भी स्तर से कहीं ऊँचा है, इसीलिए मानव-जनित तापन के आकलनों में आइस कोर केंद्रीय साक्ष्य हैं।', concept_group_id = 'l3-t1-env-ice-cores-past-air', source_citation = 'IPCC Sixth Assessment Report (AR6), Working Group I (paleoclimate assessment); National Centre for Polar and Ocean Research.', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "they hold microbes from past ages whose decay rates are used to date volcanic eruptions on other continents", "body_hi": "उनमें पिछले युगों के सूक्ष्मजीव होते हैं जिनकी क्षय-दर से दूसरे महाद्वीपों के ज्वालामुखी विस्फोटों की तिथि तय होती है", "isCorrect": false}, {"id": "b", "body": "they record the eleven-year sunspot cycle through changes in the thickness of each winter''s snow layer", "body_hi": "वे हर सर्दी की हिम-परत की मोटाई में परिवर्तन के माध्यम से ग्यारह-वर्षीय सौर-कलंक चक्र को दर्ज करते हैं", "isCorrect": false}, {"id": "c", "body": "bubbles in them preserve samples of past air, showing greenhouse-gas levels over many millennia", "body_hi": "उनके बुलबुलों में पिछली हवा के नमूने बचे रहते हैं, जो हज़ारों वर्षों के ग्रीनहाउस-गैस स्तर दिखाते हैं", "isCorrect": true}, {"id": "d", "body": "their temperature at depth shows directly how warm the oceans were at each period of the past", "body_hi": "गहराई पर उनका तापमान सीधे बताता है कि अतीत के हर काल में महासागर कितने गर्म थे", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l3-t1-env-arctic-amplification-albedo' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'mcq', difficulty = 'easy', body = 'Sister Nivedita, the Irish-born educationist who opened a school for girls in Calcutta and wrote on Indian art and nationalism, was a disciple of:', body_hi = 'आयरलैंड में जन्मी शिक्षाविद् भगिनी निवेदिता, जिन्होंने कलकत्ता में लड़कियों का विद्यालय खोला और भारतीय कला तथा राष्ट्रवाद पर लिखा, किनकी शिष्या थीं?', explanation = 'Margaret Noble met Vivekananda in London in 1895, came to India in 1898 and was given the name Nivedita, ''the dedicated'', when he initiated her; she opened a girls'' school in Bagbazar, nursed the sick during the plague of 1899, encouraged scientists such as J.C. Bose and artists of the Bengal school, and became an influential voice of nationalism during the Swadeshi years. Ramakrishna was Vivekananda''s own teacher, who died in 1886; Dayananda founded the Arya Samaj; and Annie Besant led the Theosophical Society and the Home Rule movement.', explanation_hi = 'मार्गरेट नोबल 1895 में लंदन में विवेकानंद से मिलीं, 1898 में भारत आईं और जब उन्होंने उन्हें दीक्षा दी तो उन्हें ''समर्पित'' अर्थ वाला नाम निवेदिता मिला; उन्होंने बागबाज़ार में लड़कियों का विद्यालय खोला, 1899 के प्लेग में बीमारों की सेवा की, जे.सी. बोस जैसे वैज्ञानिकों और बंगाल शैली के कलाकारों को प्रोत्साहित किया, और स्वदेशी वर्षों में राष्ट्रवाद की प्रभावशाली आवाज़ बनीं। रामकृष्ण विवेकानंद के अपने गुरु थे, जिनकी 1886 में मृत्यु हुई; दयानंद ने आर्य समाज की स्थापना की; और एनी बेसेंट ने थियोसोफ़िकल सोसाइटी और होम रूल आंदोलन का नेतृत्व किया।', concept_group_id = 'l3-t1-his-sister-nivedita', source_citation = 'NCERT Class XII, Themes in Indian History III; NCERT (old), Modern India; Ramakrishna Mission.', question_data = '{"craft": "recall"}'::jsonb, options = '[{"id": "a", "body": "Ramakrishna Paramahamsa", "body_hi": "रामकृष्ण परमहंस", "isCorrect": false}, {"id": "b", "body": "Dayananda Saraswati", "body_hi": "दयानंद सरस्वती", "isCorrect": false}, {"id": "c", "body": "Annie Besant", "body_hi": "एनी बेसेंट", "isCorrect": false}, {"id": "d", "body": "Swami Vivekananda", "body_hi": "स्वामी विवेकानंद", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l3-t1-his-ina-red-fort-trial' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Modern', type = 'statement_based', difficulty = 'easy', body = 'Consider the following statements about the Hindu Mela:', body_hi = 'हिंदू मेले के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Both statements are correct. The Hindu Mela, organised by Nabagopal Mitra with Dwijendranath and Ganendranath Tagore among its patrons, held annual gatherings with exhibitions of Indian crafts, wrestling and patriotic songs, and urged self-help in industry and education decades before the Swadeshi movement; in 1875 the fourteen-year-old Rabindranath recited a poem there, one of his first public appearances. Historians treat it as an early sign of the cultural nationalism that later shaped the Indian Association and the Congress in Bengal.', explanation_hi = 'दोनों कथन सही हैं। नवगोपाल मित्र द्वारा आयोजित हिंदू मेला, जिसके संरक्षकों में द्विजेंद्रनाथ और गणेंद्रनाथ टैगोर थे, भारतीय शिल्पों की प्रदर्शनियों, कुश्ती और देशभक्ति गीतों के साथ वार्षिक आयोजन करता था, और स्वदेशी आंदोलन से दशकों पहले उद्योग और शिक्षा में आत्मनिर्भरता का आग्रह करता था; 1875 में चौदह वर्षीय रवींद्रनाथ ने वहाँ एक कविता पढ़ी, जो उनकी पहली सार्वजनिक उपस्थितियों में से एक थी। इतिहासकार इसे उस सांस्कृतिक राष्ट्रवाद का आरंभिक संकेत मानते हैं जिसने बाद में बंगाल में इंडियन एसोसिएशन और कांग्रेस को आकार दिया।', concept_group_id = 'l3-t1-his-hindu-mela-1867', source_citation = 'NCERT Class XII, Themes in Indian History III; NCERT (old), Modern India.', question_data = '{"statements": ["It was started in Calcutta in 1867, with the support of the Tagore family, to foster national pride and Indian crafts and industry.", "As a boy, Rabindranath Tagore recited a patriotic poem of his own at one of its gatherings."], "statements_hi": ["इसे 1867 में कलकत्ता में, टैगोर परिवार के सहयोग से, राष्ट्रीय गौरव और भारतीय शिल्प तथा उद्योग को बढ़ावा देने के लिए शुरू किया गया।", "बालक के रूप में रवींद्रनाथ टैगोर ने इसके एक आयोजन में अपनी एक देशभक्ति कविता का पाठ किया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true, "craft": "recall"}'::jsonb, options = '[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l3-t1-his-rin-ratings-revolt-1946' returning concept_group_id;
update public.questions set subject = 'Polity', topic = 'Federalism & Special Provisions', type = 'statement_based', difficulty = 'medium', body = 'With reference to the Supreme Court''s nine-judge decision in Jindal Stainless Ltd. v. State of Haryana (2016), consider the following statements:', body_hi = 'जिंदल स्टेनलेस लिमिटेड बनाम हरियाणा राज्य (2016) में सर्वोच्च न्यायालय के नौ न्यायाधीशों के निर्णय के संदर्भ में, निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'Only statement 1 is correct. States had long levied entry taxes on goods brought in from other States, and traders argued that these hit the freedom of trade in Article 301 unless they were ''compensatory'' or cleared under Article 304(b). The nine-judge bench rejected the compensatory-tax test and held that taxes are not, as such, restrictions on trade; only a tax that discriminates against goods from other States, in favour of local goods, offends Article 304(a). Statements 2 and 3 are wrong: a non-discriminatory entry tax needed no presidential sanction, so the States kept the power, and the cases on whether particular levies were discriminatory went back to regular benches. Entry taxes were later subsumed into the GST in 2017.', explanation_hi = 'केवल कथन 1 सही है। राज्य लंबे समय से दूसरे राज्यों से लाई गई वस्तुओं पर प्रवेश-कर लगाते रहे थे, और व्यापारियों का तर्क था कि जब तक वे ''प्रतिपूरक'' न हों या अनुच्छेद 304(ख) के अंतर्गत स्वीकृत न हों, वे अनुच्छेद 301 की व्यापार-स्वतंत्रता पर चोट करते हैं। नौ न्यायाधीशों की पीठ ने प्रतिपूरक-कर की कसौटी ख़ारिज की और माना कि कर अपने-आप में व्यापार पर प्रतिबंध नहीं हैं; केवल वही कर अनुच्छेद 304(क) का उल्लंघन करता है जो स्थानीय वस्तुओं के पक्ष में दूसरे राज्यों की वस्तुओं से भेदभाव करे। कथन 2 और 3 ग़लत हैं: भेदभाव-रहित प्रवेश-कर के लिए राष्ट्रपति की मंज़ूरी आवश्यक नहीं थी, इसलिए राज्यों की शक्ति बनी रही, और कोई विशेष कर भेदभावपूर्ण है या नहीं, इसके मामले सामान्य पीठों को लौटाए गए। बाद में 2017 में प्रवेश-कर GST में समाहित हो गए।', concept_group_id = 'l3-t1-pol-jindal-stainless-entry-tax', source_citation = 'Supreme Court of India: Jindal Stainless Ltd. v. State of Haryana (2016); Constitution of India, Articles 301 and 304.', question_data = '{"statements": ["It held that a non-discriminatory tax is not, by itself, a restriction on the freedom of trade guaranteed by Article 301.", "It held that every State tax on goods entering from another State needs the President''s previous sanction.", "After the judgment, the States lost all power to levy an entry tax on goods."], "statements_hi": ["इसने माना कि भेदभाव-रहित कर अपने-आप में अनुच्छेद 301 द्वारा प्रत्याभूत व्यापार की स्वतंत्रता पर प्रतिबंध नहीं है।", "इसने माना कि दूसरे राज्य से आने वाली वस्तुओं पर हर राज्य-कर के लिए राष्ट्रपति की पूर्व मंज़ूरी चाहिए।", "इस निर्णय के बाद राज्यों ने वस्तुओं पर प्रवेश-कर लगाने की सारी शक्ति खो दी।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "precision"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l3-t1-pol-part-xiii-trade-301-304' returning concept_group_id;
update public.questions set subject = 'Science & Technology', topic = 'Energy & Environmental Technology', type = 'statement_based', difficulty = 'medium', body = 'Consider the following statements about green ammonia:', body_hi = 'हरित अमोनिया के बारे में निम्नलिखित कथनों पर विचार कीजिए:', explanation = 'All four statements are correct. Ammonia (NH3) is made by the Haber process, which joins nitrogen and hydrogen over an iron catalyst at high pressure; it is ''green'' when the hydrogen comes from splitting water with renewable power rather than from natural gas, whose use releases carbon dioxide. Hydrogen has to be cooled to about −253 °C or squeezed to very high pressure, while ammonia liquefies easily and can use existing tankers and terminals, so it is a favoured way of carrying hydrogen; it can be burnt directly in ships'' engines and power plants, or cracked back into hydrogen. Its drawbacks are its toxicity and the oxides of nitrogen formed when it burns. In 2025 the Solar Energy Corporation of India ran auctions under the Mission''s SIGHT programme to supply green ammonia to fertiliser units, the largest users of ammonia in India.', explanation_hi = 'चारों कथन सही हैं। अमोनिया (NH3) हेबर प्रक्रम से बनती है, जो उच्च दाब पर लोहे के उत्प्रेरक की उपस्थिति में नाइट्रोजन और हाइड्रोजन को जोड़ता है; यह ''हरित'' तब होती है जब हाइड्रोजन प्राकृतिक गैस से नहीं, जिसके उपयोग से कार्बन डाइऑक्साइड निकलती है, बल्कि नवीकरणीय बिजली से पानी के अपघटन से आए। हाइड्रोजन को लगभग −253 °C तक ठंडा करना या बहुत ऊँचे दाब पर दबाना पड़ता है, जबकि अमोनिया आसानी से द्रवित होती है और मौजूदा टैंकरों और टर्मिनलों का उपयोग कर सकती है, इसलिए यह हाइड्रोजन ढोने का एक पसंदीदा तरीक़ा है; इसे जहाज़ों के इंजनों और बिजलीघरों में सीधे जलाया जा सकता है, या वापस हाइड्रोजन में तोड़ा जा सकता है। इसकी कमियाँ इसकी विषाक्तता और जलने पर बनने वाले नाइट्रोजन के ऑक्साइड हैं। 2025 में भारतीय सौर ऊर्जा निगम ने मिशन के SIGHT कार्यक्रम के अंतर्गत उर्वरक इकाइयों, जो भारत में अमोनिया की सबसे बड़ी उपयोगकर्ता हैं, को हरित अमोनिया की आपूर्ति के लिए नीलामियाँ कीं।', concept_group_id = 'l3-t1-sci-green-ammonia-carrier', source_citation = 'Ministry of New and Renewable Energy (National Green Hydrogen Mission; SIGHT programme); NCERT Class XI, Chemistry (Equilibrium: the Haber process).', question_data = '{"statements": ["Where hydrogen itself is needed, ammonia can be ''cracked'' back into hydrogen and nitrogen.", "It is easier to store and ship than hydrogen, since ammonia turns liquid at about −33 °C at normal atmospheric pressure.", "Burning ammonia releases no carbon dioxide, though it can produce oxides of nitrogen.", "In India, auctions held under the National Green Hydrogen Mission have sought green ammonia for fertiliser plants, which otherwise make ammonia from natural gas."], "statements_hi": ["जहाँ स्वयं हाइड्रोजन चाहिए, वहाँ अमोनिया को फिर से हाइड्रोजन और नाइट्रोजन में तोड़ा (‘क्रैक’ किया) जा सकता है।", "इसे हाइड्रोजन की तुलना में भंडारित करना और जहाज़ से भेजना आसान है, क्योंकि अमोनिया सामान्य वायुमंडलीय दाब पर लगभग −33 °C पर द्रव बन जाती है।", "अमोनिया जलाने पर कार्बन डाइऑक्साइड नहीं निकलती, यद्यपि नाइट्रोजन के ऑक्साइड बन सकते हैं।", "भारत में राष्ट्रीय हरित हाइड्रोजन मिशन के अंतर्गत हुई नीलामियों में उर्वरक संयंत्रों के लिए हरित अमोनिया माँगी गई है, जो अन्यथा प्राकृतिक गैस से अमोनिया बनाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft') and concept_group_id = 'l3-t1-sci-green-ammonia-carrier' returning concept_group_id;
commit;
